use vstd::prelude::*;

verus! {
    /// Given an array `a` of `i32`, returns `(found, index)` such that:
    /// - If `found` is false, then every element in `a` is even.
    /// - If `found` is true, then `index` is the first position in `a`
    ///   where `a[index]` is odd, and all earlier elements are even.
    fn find_first_odd(a: &[i32]) -> (found: bool, index: usize)
        ensures
            // No odd element anywhere if not found
            !found ==> forall|i: usize| i < a.len() ==> a[i] % 2 == 0,
        ensures
            // If found, index is in bounds, that element is odd,
            // and all earlier ones are even
            found ==>
                index < a.len() &&
                a[index] % 2 != 0 &&
                forall|i: usize| i < index ==> a[i] % 2 == 0,
    {
        let mut idx: usize = 0;
        let mut found: bool = false;
        let mut first_index: usize = 0;
        // Scan until we either reach the end or find an odd
        while idx < a.len() && !found
            invariant
                idx <= a.len(),
                // So far, if we haven't found an odd, all seen are even
                !found ==> forall|j: usize| j < idx ==> a[j] % 2 == 0,
                // If we have found one, first_index marks its location,
                // that element is odd, and all earlier ones were even
                found ==> first_index <= idx &&
                           a[first_index] % 2 != 0 &&
                           forall|j: usize| j < first_index ==> a[j] % 2 == 0,
            decreases
                a.len() - idx,
        {
            if a[idx] % 2 != 0 {
                // We found the first odd at position idx
                found = true;
                first_index = idx;
            } else {
                // Still even, keep scanning
                idx = idx + 1;
            }
        }
        // Return according to whether we found an odd
        if found {
            (true, first_index)
        } else {
            // arbitrary index when none found
            (false, 0)
        }
    }
}

fn main() {
    // Example usage (not verified):
    let a1: Vec<i32> = vec![2, 4, 6];
    assert_eq!(find_first_odd(&a1), (false, 0));

    let a2: Vec<i32> = vec![2, 4, 5, 8];
    assert_eq!(find_first_odd(&a2), (true, 2));
}